-- Run once in Supabase SQL Editor.
create table if not exists public.endless_horde_scores (user_id uuid not null references auth.users(id) on delete cascade,map_id text not null,best_wave integer not null default 0,best_kills integer not null default 0,best_seconds integer not null default 0,updated_at timestamptz not null default now(),primary key(user_id,map_id));
alter table public.endless_horde_scores enable row level security; revoke all on public.endless_horde_scores from anon,authenticated;
create or replace function public.submit_endless_horde_score(p_map_id text,p_wave integer,p_kills integer,p_seconds integer) returns void language plpgsql security definer set search_path=public,auth as $$ begin if auth.uid() is null then raise exception 'Sign in required'; end if; if p_map_id not in ('zombie-varrock','zombie-falador','zombie-morytania') then raise exception 'Invalid map'; end if; insert into public.endless_horde_scores(user_id,map_id,best_wave,best_kills,best_seconds) values(auth.uid(),p_map_id,greatest(1,p_wave),greatest(0,p_kills),greatest(0,p_seconds)) on conflict(user_id,map_id) do update set best_wave=greatest(endless_horde_scores.best_wave,excluded.best_wave),best_kills=case when excluded.best_wave>=endless_horde_scores.best_wave then excluded.best_kills else endless_horde_scores.best_kills end,best_seconds=case when excluded.best_wave>=endless_horde_scores.best_wave then excluded.best_seconds else endless_horde_scores.best_seconds end,updated_at=now(); end $$;
create or replace function public.get_endless_horde_leaderboard() returns table(username text,map_id text,best_wave integer,best_kills integer,best_seconds integer) language sql stable security definer set search_path=public as $$ select c.username,s.map_id,s.best_wave,s.best_kills,s.best_seconds from public.endless_horde_scores s join public.characters c on c.user_id=s.user_id order by s.best_wave desc,s.best_kills desc,s.best_seconds desc limit 50 $$;
grant execute on function public.submit_endless_horde_score(text,integer,integer,integer) to authenticated; grant execute on function public.get_endless_horde_leaderboard() to anon,authenticated;
